ó salva se você solicitar."}[language];HelpEyebrow.Text=new[]{"BESOIN D’UN COUP DE MAIN ?","NEED A HAND?","¿NECESITAS AYUDA?","BRAUCHST DU HILFE?","PRECISA DE AJUDA?"}[language];HelpTitle.Text=new[]{"Aide","Help","Ayuda","Hilfe","Ajuda"}[language];HelpSubtitle.Text=new[]{"Les réponses aux questions courantes.","Answers to common questions.","Respuestas a preguntas frecuentes.","Antworten auf häufige Fragen.","Respostas às perguntas frequentes."}[language];HelpQuestion1.Text=new[]{"Mes batteries ne s’affichent pas","My battery levels aren’t showing","No aparecen los niveles de batería","Meine Akkustände werden nicht angezeigt","Os níveis de bateria não aparecem"}[language];HelpAnswer1.Text=new[]{"Vérifiez que les AirPods sont connectés à Windows, puis ouvrez leur boîtier près du PC. Si nécessaire, sélectionnez un signal dans les options de détection.","Make sure the AirPods are connected to Windows, then open the case near the PC. If needed, select a signal in detection options.","Comprueba que los AirPods estén conectados a Windows y abre el estuche cerca del PC. Si hace falta, selecciona una señal en las opciones de detección.","Prüfe die Windows-Verbindung und öffne das Case in PC-Nähe. Wähle bei Bedarf ein Signal in den Erkennungsoptionen.","Confirme que os AirPods estão conectados ao Windows e abra o estojo perto do PC. Se necessário, selecione um sinal nas opções de detecção."}[language];HelpQuestion2.Text=new[]{"Pourquoi les pourcentages sont-ils approximatifs ?","Why are the percentages approximate?","¿Por qué son aproximados los porcentajes?","Warum sind die Prozentwerte ungefähr?","Por que as porcentagens são aproximadas?"}[language];HelpAnswer2.Text=new[]{"Les annonces Bluetooth utilisées indiquent les niveaux par paliers de 10 %. L’association automatique est une estimation et peut confondre une autre paire proche.","Bluetooth advertisements report levels in 10% steps. Automatic association is an estimate and may mistake another nearby pair.","Los anuncios Bluetooth indican niveles en pasos del 10 %. La asociación automática es estimada y puede confundir otro par cercano.","Bluetooth-Signale melden Werte in 10-%-Schritten. Die automatische Zuordnung ist eine Schätzung und kann ein anderes Paar verwechseln.","Os sinais Bluetooth informam níveis em passos de 10%. A associação automática é estimada e pode confundir outro par próximo."}[language];HelpQuestion3.Text=new[]{"L’application continue après la fermeture","The app keeps running after closing","La aplicación sigue funcionando al cerrarla","Die App läuft nach dem Schließen weiter","O aplicativo continua após fechar"}[language];HelpAnswer3.Text=new[]{"La fenêtre se réduit dans la zone de notification. Pour arrêter l’application, faites un clic droit sur son icône puis choisissez Quitter.","Closing hides the window in the system tray. To stop the app, right-click its icon and choose Quit.","Al cerrar, la ventana queda en el área de notificación. Para salir, haz clic derecho en el icono y elige Quit.","Beim Schließen bleibt die App im Infobereich. Zum Beenden das Symbol rechtsklicken und Quit wählen.","Ao fechar, a janela fica na área de notificação. Para encerrar, clique com o botão direito no ícone e escolha Quit."}[language];RenderHistory();UpdateBadge();UpdateAge(); ((ComboBoxItem)Theme.Items[0]).Content=w[20];((ComboBoxItem)Theme.Items[1]).Content=w[21];}
 sealed class Preferences {public int Theme {get;set;} public int Language {get;set;} public bool Notifications {get;set;}=true; public int Threshold {get;set;}=20;}
 void Save(){if(!ready)return;try{Directory.CreateDirectory(Path.GetDirectoryName(settingsFile)!);File.WriteAllText(settingsFile,JsonSerializer.Serialize(new Preferences{Theme=Theme.SelectedIndex,Language=LanguagePicker.SelectedIndex,Notifications=notificationsEnabled,Threshold=alertThreshold}));}catch{}}
 bool IsLowBattery(int left,int right)=>(left<=10&&left*10<=alertThreshold)||(right<=10&&right*10<=alertThreshold);
 void ThresholdChanged(object s,SelectionChangedEventArgs e){if(!ready)return;alertThreshold=(Threshold.SelectedIndex+1)*10;lowBatteryNotified=false;Save();}
 void PreferencesChanged(object s,RoutedEventArgs e){if(!ready)return;notificationsEnabled=NotificationsToggle.IsChecked==true;Threshold.IsEnabled=notificationsEnabled;Save();}
 const string RunKey=@"Software\Microsoft\Windows\CurrentVersion\Run";
 bool StartupEnabled(){try{using var k=Registry.CurrentUser.OpenSubKey(RunKey);return k?.GetValue("PodsDesk") is string value && value.Contains(Environment.ProcessPath??"",StringComparison.OrdinalIgnoreCase);}catch{return false;}}
 void StartupChanged(object s,RoutedEventArgs e){if(!ready)return;try{using var k=Registry.CurrentUser.CreateSubKey(RunKey);if(StartupToggle.IsChecked==true)k.SetValue("PodsDesk",$"\"{Environment.ProcessPath}\" --background");else k.DeleteValue("PodsDesk",false);}catch{StartupToggle.IsChecked=StartupEnabled();System.Windows.MessageBox.Show(new[]{"Impossible de modifier le démarrage automatique.","Could not change automatic startup.","No se pudo modificar el inicio automático.","Der Autostart konnte nicht geändert werden.","Não foi possível alterar a inicialização automática."}[language],"PodsDesk");}}
 sealed record BatterySample(DateTime Time,int? Left,int? Right,int? Case);
 void RecordBattery(int left,int right,int box){int? l=left<=10?left*10:null,r=right<=10?right*10:null,c=box<=10?box*10:null;if(l==null&&r==null&&c==null)return;var last=history.LastOrDefault();if(last!=null&&last.Left==l&&last.Right==r&&last.Case==c)return;history.Add(new BatterySample(DateTime.Now,l,r,c));if(history.Count>50)history.RemoveAt(0);RenderHistory();}
 void ClearHistory(){history.Clear();RenderHistory();}
 void ClearHistoryClick(object s,RoutedEventArgs e)=>ClearHistory();
 void RenderHistory(){HistoryList.Items.Clear();string[] shortLabels=language switch{0=>new[]{"G","D","Boîtier"},1=>new[]{"L","R","Case"},2=>new[]{"I","D","Estuche"},3=>new[]{"L","R","Case"},_=>new[]{"E","D","Estojo"}};string Value(int? n)=>n.HasValue?$"{n}%":"—";foreach(var item in history.AsEnumerable().Reverse())HistoryList.Items.Add($"{item.Time:HH:mm:ss}     {shortLabels[0]}  {Value(item.Left)}       {shortLabels[1]}  {Value(item.Right)}       {shortLabels[2]}  {Value(item.Case)}");HistoryEmpty.Visibility=history.Count==0?Visibility.Visible:Visibility.Collapsed;ExportHistoryButton.IsEnabled=history.Count>0;ClearHistoryButton.IsEnabled=history.Count>0;}
 IEnumerable<string> HistoryCsv(){yield return "timestamp,left_percent,right_percent,case_percent";foreach(var x in history)yield return $"{x.Time:O},{x.Left?.ToString(System.Globalization.CultureInfo.InvariantCulture)},{x.Right?.ToString(System.Globalization.CultureInfo.InvariantCulture)},{x.Case?.ToString(System.Globalization.CultureInfo.InvariantCulture)}";}
 void ExportHistoryClick(object s,RoutedEventArgs e){if(history.Count==0)return;var dialog=new Microsoft.Win32.SaveFileDialog{Filter="CSV (*.csv)|*.csv",FileName="PodsDesk-batterie.csv",DefaultExt=".csv"};if(dialog.ShowDialog(this)!=true)return;try{File.WriteAllLines(dialog.FileName,HistoryCsv(),System.Text.Encoding.UTF8);}catch{System.Windows.MessageBox.Show(new[]{"Impossible d’exporter les mesures.","Could not export the readings.","No se pudieron exportar los datos.","Die Werte konnten nicht exportiert werden.","Não foi possível exportar as medições."}[language],"PodsDesk");}}
 void ClearBattery(){LeftValue.Text=RightValue.Text=CaseValue.Text="—";AnimateBar(LeftBar,0);AnimateBar(RightBar,0);AnimateBar(CaseBar,0);LeftCharge.Text=RightCharge.Text=CaseCharge.Text=" ";SetTrayBattery(null);UpdateAge();}
 [System.Runtime.InteropServices.DllImport("user32.dll")] static extern bool DestroyIcon(IntPtr handle);
 void SetTrayBattery(int? percent){if(tray==null)return;string label=percent?.ToString()??"·";if(trayDisplay==label)return;trayDisplay=label;using var bmp=new System.Drawing.Bitmap(32,32);using(var g=System.Drawing.Graphics.FromImage(bmp)){g.SmoothingMode=System.Drawing.Drawing2D.SmoothingMode.AntiAlias;g.TextRenderingHint=System.Drawing.Text.TextRenderingHint.AntiAliasGridFit;using var bg=new System.Drawing.SolidBrush(System.Drawing.Color.FromArgb(38,38,38));g.FillEllipse(bg,1,1,30,30);using var font=new System.Drawing.Font("Segoe UI",label.Length>=3?10:12,System.Drawing.FontStyle.Bold,System.Drawing.GraphicsUnit.Pixel);using var white=new System.Drawing.SolidBrush(System.Drawing.Color.White);using var format=new System.Drawing.StringFormat{Alignment=System.Drawing.StringAlignment.Center,LineAlignment=System.Drawing.StringAlignment.Center};g.DrawString(label,font,white,new System.Drawing.RectangleF(0,0,32,32),format);}var handle=bmp.GetHicon();try{using var temporary=System.Drawing.Icon.FromHandle(handle);var next=(System.Drawing.Icon)temporary.Clone();tray.Icon=next;var old=batteryIcon;batteryIcon=next;old?.Dispose();}finally{DestroyIcon(handle);}}
 string ChargingText()=>new[]{"↗  En charge","↗  Charging","↗  Cargando","↗  Wird geladen","↗  Carregando"}[language];
 void UpdateAge(){if((DateTime.Now-seen).TotalSeconds>60){LastUpdate.Text=new[]{"En attente de données","Waiting for data","Esperando datos","Warte auf Daten","Aguardando dados"}[language];return;}int n=Math.Max(0,(int)(DateTime.Now-seen).TotalSeconds);LastUpdate.Text=new[]{$"Mis à jour il y a {n} s",$"Updated {n}s ago",$"Actualizado hace {n} s",$"Aktualisiert vor {n} s",$"Atualizado há {n} s"}[language];}
 void SetNavigation(bool ignored){var buttons=new[]{HomeButton,BatteryButton,SettingsButton,HelpButton};for(int i=0;i<buttons.Length;i++){buttons[i].Background=(System.Windows.Media.Brush)Resources[i==currentPage?"AccentSoft":"Side"];buttons[i].Foreground=(System.Windows.Media.Brush)Resources[i==currentPage?"AccentText":"Muted"];}}
 void AnimateBar(System.Windows.Controls.ProgressBar bar,double target){if(bar.Tag is double last && last==target)return;bar.Tag=target;bar.BeginAnimation(System.Windows.Controls.ProgressBar.ValueProperty,new DoubleAnimation(bar.Value,target,TimeSpan.FromMilliseconds(550)){EasingFunction=new CubicEase{EasingMode=EasingMode.EaseOut}});}
 void AnimateEntrance(UIElement panel){panel.BeginAnimation(UIElement.OpacityProperty,new DoubleAnimation(0,1,TimeSpan.FromMilliseconds(300)){EasingFunction=new CubicEase{EasingMode=EasingMode.EaseOut}});var transform=new TranslateTransform();panel.RenderTransform=transform;transform.BeginAnimation(TranslateTransform.YProperty,new DoubleAnimation(12,0,TimeSpan.FromMilliseconds(340)){EasingFunction=new CubicEase{EasingMode=EasingMode.EaseOut}});}
 void SelectPage(int page){currentPage=page;Home.Visibility=page==0?Visibility.Visible:Visibility.Collapsed;BatteryPage.Visibility=page==1?Visibility.Visible:Visibility.Collapsed;Settings.Visibility=page==2?Visibility.Visible:Visibility.Collapsed;HelpPage.Visibility=page==3?Visibility.Visible:Visibility.Collapsed;SetNavigation(page==2);UIElement panel=page==0?Home:page==1?BatteryPage:page==2?Settings:HelpPage;AnimateEntrance(panel);}
 void NavigatePage(bool settings)=>SelectPage(settings?2:0);
 void ShowBattery(object s,RoutedEventArgs e)=>SelectPage(1); void ShowHelp(object s,RoutedEventArgs e)=>SelectPage(3);
 void AdvancedExpanded(object s,RoutedEventArgs e)=>AnimateEntrance(AdvancedDetails);
 void ThemeChanged(object s,SelectionChangedEventArgs e){if(!ready)return;ApplyTheme();Save();} void LanguageChanged(object s,SelectionChangedEventArgs e){if(!ready)return;ApplyLanguage();Save();} void ShowHome(object s,RoutedEventArgs e)=>NavigatePage(false); void ShowSettings(object s,RoutedEventArgs e)=>NavigatePage(true); void OpenBluetooth(object s,RoutedEventArgs e)=>Process.Start(new ProcessStartInfo("ms-settings:bluetooth"){UseShellExecute=true}); void Navigate(object s,System.Windows.Navigation.RequestNavigateEventArgs e)=>Process.Start(new ProcessStartInfo(e.Uri.AbsoluteUri){UseShellExecute=true});
